function a(){console.group("🔍 Firebase Auth Debug"),console.log("📦 Session Storage:");for(let o=0;o<sessionStorage.length;o++){const e=sessionStorage.key(o);e&&(e.includes("firebase")||e.includes("auth"))&&console.log(`  ${e}:`,sessionStorage.getItem(e))}console.log("📦 Local Storage (Firebase keys):");for(let o=0;o<localStorage.length;o++){const e=localStorage.key(o);if(e&&(e.includes("firebase")||e.includes("auth")))try{const s=localStorage.getItem(e);try{const n=JSON.parse(s||"{}");console.log(`  ${e}:`,n)}catch{console.log(`  ${e}:`,s)}}catch{console.log(`  ${e}: <could not read>`)}}console.groupEnd();const t=[],l=[];for(let o=0;o<sessionStorage.length;o++){const e=sessionStorage.key(o);e&&(e.includes("firebase")||e.includes("auth"))&&t.push({key:e,value:sessionStorage.getItem(e)})}for(let o=0;o<localStorage.length;o++){const e=localStorage.key(o);e&&(e.includes("firebase")||e.includes("auth"))&&l.push({key:e,value:localStorage.getItem(e)})}return{sessionStorage:t,localStorage:l}}typeof window!="undefined"&&(window.debugFirebaseAuth=a);export{a as debugFirebaseAuth};
